<script>
(() => {
  const root = document.getElementById("viz-residuos");
  const dataNode = document.getElementById("viz-residuos-data");
  if (!root || !dataNode || root.dataset.initialized === "true") return;
  root.dataset.initialized = "true";

  let payload;
  try {
    payload = JSON.parse(dataNode.textContent);
  } catch (e) {
    root.querySelector('[data-role="status"]').textContent = "No fue posible cargar los datos de la visualización.";
    return;
  }

  const meanX = Number(payload.medias.escolaridad);
  const meanY = Number(payload.medias.ingreso);
  const points = (payload.puntos || []).map(d => ({
    id: Number(d.id),
    escolaridad: Number(d.escolaridad),
    ingreso: Number(d.ingreso)
  })).filter(d => Number.isFinite(d.escolaridad) && Number.isFinite(d.ingreso));

  if (!points.length || !Number.isFinite(meanX) || !Number.isFinite(meanY)) {
    root.querySelector('[data-role="status"]').textContent = "No hay datos válidos para construir la visualización.";
    return;
  }

  const svg = root.querySelector("svg");
  const panel = root.querySelector('[data-role="panel"]');
  const status = root.querySelector('[data-role="status"]');
  const buttons = [...root.querySelectorAll("[data-zone]")];
  const NS = "http://www.w3.org/2000/svg";

  const fmt1 = new Intl.NumberFormat("es-CL",{minimumFractionDigits:1,maximumFractionDigits:1});
  const fmt0 = new Intl.NumberFormat("es-CL",{maximumFractionDigits:0});
  const fmtMoneyAxis = new Intl.NumberFormat("es-CL",{maximumFractionDigits:1});
  const money = v => "$" + fmt0.format(Math.round(v));
  const signedNumber = v => Math.abs(v)<1e-10 ? "0,0" : (v>0?"+":"−")+fmt1.format(Math.abs(v));
  const signedMoney = v => Math.abs(v)<0.5 ? "$0" : (v>0?"+":"−")+"$"+fmt0.format(Math.abs(Math.round(v)));
  const signedInteger = v => Math.abs(v)<0.5 ? "0" : (v>0?"+":"−")+fmt0.format(Math.abs(Math.round(v)));
  const axisMoney = v => Math.abs(v)>=1000000 ? fmtMoneyAxis.format(v/1000000)+" M" : Math.abs(v)>=1000 ? fmt0.format(Math.round(v/1000))+" mil" : fmt0.format(v);

  const zoneOf = p => {
    const rx=p.escolaridad-meanX, ry=p.ingreso-meanY;
    if(rx>0&&ry>0)return"pp";
    if(rx<0&&ry<0)return"nn";
    if(rx>0&&ry<0)return"pn";
    if(rx<0&&ry>0)return"np";
    return"zero";
  };

  const exampleMap = {};
  for (const ex of payload.ejemplos || []) {
    const e={escolaridad:Number(ex.escolaridad),ingreso:Number(ex.ingreso)};
    const z=zoneOf(e);
    if(z==="zero"||exampleMap[z])continue;
    const match=points.find(p=>p.escolaridad===e.escolaridad&&p.ingreso===e.ingreso);
    if(match)exampleMap[z]=match;
  }
  for(const z of ["pp","nn","pn","np"]) if(!exampleMap[z]) exampleMap[z]=points.find(p=>zoneOf(p)===z)||null;

  let selected=exampleMap.pp||points[0];
  let lastWidth=0;

  const quantile98 = values => {
    const s=[...values].sort((a,b)=>a-b);
    return s[Math.max(0,Math.min(s.length-1,Math.floor((s.length-1)*.98)))];
  };
  const niceStep=(span,target)=>{
    const rough=span/Math.max(1,target), power=10**Math.floor(Math.log10(Math.max(rough,1e-12))), error=rough/power;
    return (error>=5?5:error>=2?2:1)*power;
  };
  const makeTicks=(min,max,target)=>{
    const step=niceStep(max-min,target),start=Math.ceil(min/step)*step,t=[];
    for(let v=start;v<=max+step*.001;v+=step)t.push(v);
    return t;
  };
  const el=(tag,attrs={})=>{
    const n=document.createElementNS(NS,tag);
    Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,String(v)));
    return n;
  };

  function explanation(p){
    const rx=p.escolaridad-meanX,ry=p.ingreso-meanY;
    if(rx>0&&ry>0)return"Esta persona se encuentra sobre ambas medias. Como los dos residuos tienen el mismo signo, su producto es positivo.";
    if(rx<0&&ry<0)return"Esta persona se encuentra bajo ambas medias. Como los dos residuos tienen el mismo signo, su producto es positivo.";
    if(rx>0&&ry<0)return"Esta persona está sobre la media de escolaridad y bajo la media de ingreso. Como los residuos tienen signos opuestos, su producto es negativo.";
    if(rx<0&&ry>0)return"Esta persona está bajo la media de escolaridad y sobre la media de ingreso. Como los residuos tienen signos opuestos, su producto es negativo.";
    return"Esta persona se encuentra exactamente sobre una de las medias. Por eso uno de sus residuos es 0 y su producto también es 0.";
  }

  function updatePanel(p){
    const rx=p.escolaridad-meanX,ry=p.ingreso-meanY,prod=rx*ry;
    const sign=prod>0?"positivo":prod<0?"negativo":"cero";
    panel.querySelector('[data-field="x-value"]').textContent=fmt0.format(p.escolaridad)+" años";
    panel.querySelector('[data-field="x-mean"]').textContent=fmt1.format(meanX)+" años";
    panel.querySelector('[data-field="x-calc"]').textContent=`${fmt0.format(p.escolaridad)} − ${fmt1.format(meanX)} = ${signedNumber(rx)}`;
    panel.querySelector('[data-field="y-value"]').textContent=money(p.ingreso);
    panel.querySelector('[data-field="y-mean"]').textContent=money(meanY);
    panel.querySelector('[data-field="y-calc"]').textContent=`${money(p.ingreso)} − ${money(meanY)} = ${signedMoney(ry)}`;
    panel.querySelector('[data-field="product-calc"]').textContent=`(${signedNumber(rx)}) × (${signedInteger(ry)}) = ${signedInteger(prod)}`;
    const badge=panel.querySelector('[data-field="product-sign"]');
    badge.textContent=sign==="positivo"?"APORTE POSITIVO":sign==="negativo"?"APORTE NEGATIVO":"APORTE 0";
    badge.dataset.sign=sign;
    panel.querySelector('[data-field="explanation"]').textContent=explanation(p);
    buttons.forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.zone===zoneOf(p))));
  }

  function drawSelection(ctx){
    svg.querySelectorAll(".viz-selection-layer").forEach(n=>n.remove());
    const {sx,sy,mx,my,margin,plotRight,plotBottom,yMax}=ctx;
    const px=sx(selected.escolaridad), py=sy(selected.ingreso);
    const rx=selected.escolaridad-meanX, ry=selected.ingreso-meanY, prod=rx*ry;
    const g=el("g",{class:"viz-selection-layer","aria-hidden":"true"});
    g.appendChild(el("line",{x1:mx,x2:px,y1:py,y2:py,class:"viz-resid-x"}));
    g.appendChild(el("line",{x1:px,x2:px,y1:my,y2:py,class:"viz-resid-y"}));

    const tx=el("text",{x:(mx+px)/2,y:Math.max(margin.top+14,py-8),"text-anchor":"middle",class:"viz-resid-label viz-resid-label-x"});
    tx.textContent=`xᵢ − x̄ = ${signedNumber(rx)}`; g.appendChild(tx);

    const rightSide=px>(margin.left+plotRight)/2;
    const ty=el("text",{x:rightSide?px-8:px+8,y:(my+py)/2,"text-anchor":rightSide?"end":"start",class:"viz-resid-label viz-resid-label-y"});
    ty.textContent=`yᵢ − ȳ = ${signedMoney(ry)}`; g.appendChild(ty);

    const cls=prod>0?"viz-selected-positive":prod<0?"viz-selected-negative":"viz-selected-zero";
    g.appendChild(el("circle",{cx:px,cy:py,r:9,class:`viz-selected ${cls}`}));

    if(selected.ingreso>yMax){
      const arrow=el("text",{x:px,y:margin.top+12,"text-anchor":"middle",class:"viz-clipped-arrow"});
      arrow.textContent="↑"; g.appendChild(arrow);
    }
    svg.appendChild(g);

    // Ajustar etiquetas seg?n su tama?o real, sin reducir la fuente.
    const occupied=[...svg.querySelectorAll(".viz-mean-label, .viz-quadrant-label")]
      .map(n=>n.getBBox());
    occupied.push({x:px-12,y:py-12,width:24,height:24});
    const overlaps=(a,b)=>a.x<b.x+b.width+5&&a.x+a.width+5>b.x&&
      a.y<b.y+b.height+5&&a.y+a.height+5>b.y;
    for (const label of [tx,ty]) {
      const originalY=Number(label.getAttribute("y"));
      for (let step=0;step<40;step++) {
        const offset=step===0?0:Math.ceil(step/2)*24*(step%2?-1:1);
        label.setAttribute("y",originalY+offset);
        let box=label.getBBox();
        const shift=Math.max(0,margin.left+4-box.x)-Math.max(0,box.x+box.width-(plotRight-4));
        label.setAttribute("x",Number(label.getAttribute("x"))+shift);
        box=label.getBBox();
        if(box.y>=margin.top+4&&box.y+box.height<=plotBottom-4&&
           !occupied.some(other=>overlaps(box,other))) break;
      }
      occupied.push(label.getBBox());
    }
  }

  function draw(){
    const wrap=root.querySelector('[data-role="chart-wrap"]');
    const width=svg.getBoundingClientRect().width;
    if (!width) return;
    if(Math.abs(width-lastWidth)<2&&svg.childNodes.length){updatePanel(selected);return;}
    lastWidth=width;

    const mobile=width<560, height=mobile?430:520;
    const margin=mobile?{top:48,right:18,bottom:64,left:70}:{top:52,right:28,bottom:66,left:86};
    const innerW=width-margin.left-margin.right, innerH=height-margin.top-margin.bottom;
    svg.setAttribute("viewBox",`0 0 ${width} ${height}`);
    svg.setAttribute("height",String(height));
    while(svg.firstChild)svg.removeChild(svg.firstChild);

    const title=el("title",{id:"viz-residuos-svg-title"}); title.textContent="Posición de las personas respecto de las medias de escolaridad e ingreso"; svg.appendChild(title);
    const desc=el("desc",{id:"viz-residuos-svg-desc"}); desc.textContent="Cada punto representa una persona. Las líneas de promedio dividen el plano en cuatro zonas. Al seleccionar una persona se muestran sus residuos respecto de ambas medias."; svg.appendChild(desc);

    const xs=points.map(d=>d.escolaridad), ys=points.map(d=>d.ingreso);
    const xMinRaw=Math.min(...xs), xMaxRaw=Math.max(...xs), xPad=Math.max(.75,(xMaxRaw-xMinRaw)*.04);
    const xMin=Math.max(0,xMinRaw-xPad), xMax=xMaxRaw+xPad;
    const yMin=Math.min(0,Math.min(...ys)), yMax=Math.max(meanY*1.8,quantile98(ys),1)*1.05;

    const sx=v=>margin.left+((v-xMin)/(xMax-xMin))*innerW;
    const syRaw=v=>margin.top+(1-((v-yMin)/(yMax-yMin)))*innerH;
    const sy=v=>Math.max(margin.top,Math.min(margin.top+innerH,syRaw(v)));
    const mx=sx(meanX), my=sy(meanY), plotRight=margin.left+innerW, plotBottom=margin.top+innerH;

    const bg=el("g",{"aria-hidden":"true"});
    const zones=[
      {x:margin.left,y:margin.top,w:mx-margin.left,h:my-margin.top,cls:"viz-zone-negative",label:"− × + = −",lx:(margin.left+mx)/2,ly:margin.top+24},
      {x:mx,y:margin.top,w:plotRight-mx,h:my-margin.top,cls:"viz-zone-positive",label:"+ × + = +",lx:(mx+plotRight)/2,ly:margin.top+24},
      {x:margin.left,y:my,w:mx-margin.left,h:plotBottom-my,cls:"viz-zone-positive",label:"− × − = +",lx:(margin.left+mx)/2,ly:plotBottom-14},
      {x:mx,y:my,w:plotRight-mx,h:plotBottom-my,cls:"viz-zone-negative",label:"+ × − = −",lx:(mx+plotRight)/2,ly:plotBottom-14}
    ];
    zones.forEach(z=>{
      bg.appendChild(el("rect",{x:z.x,y:z.y,width:Math.max(0,z.w),height:Math.max(0,z.h),class:z.cls}));
      if(z.w>0&&z.h>45){const t=el("text",{x:z.lx,y:z.ly,class:"viz-quadrant-label","text-anchor":"middle"});t.textContent=z.label;bg.appendChild(t);}
    });
    svg.appendChild(bg);

    const grid=el("g",{class:"viz-grid","aria-hidden":"true"});
    makeTicks(xMin,xMax,mobile?4:6).forEach(t=>{
      const x=sx(t); grid.appendChild(el("line",{x1:x,x2:x,y1:margin.top,y2:plotBottom}));
      const l=el("text",{x,y:plotBottom+24,"text-anchor":"middle",class:"viz-axis-tick"});l.textContent=fmt0.format(t);grid.appendChild(l);
    });
    makeTicks(yMin,yMax,mobile?4:5).forEach(t=>{
      const y=sy(t); grid.appendChild(el("line",{x1:margin.left,x2:plotRight,y1:y,y2:y}));
      const l=el("text",{x:margin.left-10,y:y+4,"text-anchor":"end",class:"viz-axis-tick"});l.textContent=axisMoney(t);grid.appendChild(l);
    });
    svg.appendChild(grid);

    const means=el("g",{class:"viz-means","aria-hidden":"true"});
    means.appendChild(el("line",{x1:mx,x2:mx,y1:margin.top,y2:plotBottom,class:"viz-mean-x"}));
    means.appendChild(el("line",{x1:margin.left,x2:plotRight,y1:my,y2:my,class:"viz-mean-y"}));
    const lx=el("text",{x:Math.min(plotRight-6,mx+8),y:margin.top-14,class:"viz-mean-label viz-mean-label-x"});lx.textContent=`x̄ = ${fmt1.format(meanX)}`;means.appendChild(lx);
    const ly=el("text",{x:plotRight-6,y:Math.max(margin.top+16,my-8),"text-anchor":"end",class:"viz-mean-label viz-mean-label-y"});ly.textContent=`ȳ = ${money(meanY)}`;means.appendChild(ly);
    svg.appendChild(means);

    const pg=el("g",{class:"viz-points"});
    points.forEach(p=>{
      const c=el("circle",{cx:sx(p.escolaridad),cy:sy(p.ingreso),r:3.6,class:p.ingreso>yMax?"viz-point viz-point-clipped":"viz-point","data-id":p.id});
      c.addEventListener("click",()=>{selected=p;updatePanel(selected);drawSelection({sx,sy,mx,my,margin,plotRight,plotBottom,yMax});});
      pg.appendChild(c);
    });
    svg.appendChild(pg);
    // Las etiquetas quedan sobre los puntos para conservar su legibilidad.
    bg.querySelectorAll("text").forEach(label=>svg.appendChild(label));
    means.querySelectorAll("text").forEach(label=>svg.appendChild(label));

    const labels=el("g",{"aria-hidden":"true"});
    const xt=el("text",{x:margin.left+innerW/2,y:height-12,"text-anchor":"middle",class:"viz-axis-title"});xt.textContent="Años de escolaridad";labels.appendChild(xt);
    const yt=el("text",{x:18,y:margin.top+innerH/2,transform:`rotate(-90 18 ${margin.top+innerH/2})`,"text-anchor":"middle",class:"viz-axis-title"});yt.textContent="Ingreso de la ocupación principal";labels.appendChild(yt);
    svg.appendChild(labels);

    drawSelection({sx,sy,mx,my,margin,plotRight,plotBottom,yMax});
    updatePanel(selected);

    const clipped=points.filter(p=>p.ingreso>yMax).length;
    const note=root.querySelector('[data-role="scale-note"]');
    note.hidden=clipped===0;
    if(clipped>0)note.textContent=`Para mantener legible la nube, ${clipped} caso${clipped===1?"":"s"} con ingresos excepcionalmente altos se muestran en el borde superior. Los cálculos conservan sus valores reales.`;
  }

  buttons.forEach(b=>b.addEventListener("click",()=>{
    const p=exampleMap[b.dataset.zone];
    if(!p)return;
    selected=p;lastWidth=0;draw();
  }));

  status.textContent="Selecciona cualquier punto o usa los botones para recorrer las cuatro combinaciones.";
  const wrap=root.querySelector('[data-role="chart-wrap"]');
  if("ResizeObserver" in window){
    const ro=new ResizeObserver(()=>draw());
    ro.observe(wrap);
  } else {
    window.addEventListener("resize",draw,{passive:true});
  }
  draw();
})();
</script>

